using System;using System.Collections;using System.Collections.Generic;using System.Drawing;using System.IO;using System.Linq;using System.Net;using System.Text;using System.Threading.Tasks;using System.Windows.Forms;using Microsoft.Web.WebView2.Core;using Microsoft.Web.WebView2.WinForms;
namespace UEPLV.VeyonIntegration {
sealed class ChatWindow:Form {
 readonly bool teacher,hidden;string[] targets;string revision=Guid.NewGuid().ToString();StaffSession session;bool busy,ready,exiting,first=true;Dictionary<string,object> snapshot;
 readonly WebView2 view=new WebView2{Dock=DockStyle.Fill};readonly Timer poll=new Timer{Interval=3000},requests=new Timer{Interval=350};readonly NotifyIcon tray=new NotifyIcon{Icon=SystemIcons.Information,Text="Chat del laboratorio",Visible=true};readonly HashSet<string> seen=new HashSet<string>();public string QaPath;
 public ChatWindow(bool staff,string[] selected,bool startHidden=false){teacher=staff;targets=selected??new string[0];hidden=startHidden;Text="Chat del laboratorio";Size=new Size(1050,730);MinimumSize=new Size(720,480);StartPosition=FormStartPosition.CenterScreen;Controls.Add(view);tray.DoubleClick+=(s,e)=>Open();tray.BalloonTipClicked+=(s,e)=>Open();var menu=new ContextMenuStrip();menu.Items.Add("Abrir chat",null,(s,e)=>Open());tray.ContextMenuStrip=menu;FormClosing+=(s,e)=>{if(!exiting&&e.CloseReason==CloseReason.UserClosing){e.Cancel=true;Hide();}};FormClosed+=(s,e)=>{poll.Stop();requests.Stop();tray.Dispose();};poll.Tick+=async(s,e)=>await Poll();requests.Tick+=async(s,e)=>{if(!teacher)return;try{string file=Path.Combine(SessionStore.DirectoryPath,"chat-open.json");if(File.Exists(file)){var data=Api.Json.Deserialize<Dictionary<string,object>>(File.ReadAllText(file));targets=Options.ParseTargets(Api.String(data,"targets"));File.Delete(file);revision=Guid.NewGuid().ToString();Open();await Poll();}if(System.Diagnostics.Process.GetProcessesByName("veyon-master").Length==0&&QaPath==null){exiting=true;Close();}}catch{}};Shown+=async(s,e)=>{if(!teacher||hidden)Hide();try{await Initialize();poll.Start();if(teacher)requests.Start();}catch(Exception error){if(QaPath!=null){File.WriteAllText(QaPath,error.ToString());exiting=true;Close();}else MessageBox.Show(this,"No se pudo abrir el chat: "+error.Message,"Chat");}};}
 void Open(){Show();WindowState=FormWindowState.Normal;Activate();}
 async Task Initialize(){string profile=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"UEPLV","ChatWebView");var environment=await CoreWebView2Environment.CreateAsync(null,profile);await view.EnsureCoreWebView2Async(environment);if(QaPath!=null)File.AppendAllText(QaPath+".log","initialized\n");var core=view.CoreWebView2;core.Settings.AreDevToolsEnabled=false;core.Settings.AreDefaultContextMenusEnabled=false;core.Settings.AreHostObjectsAllowed=false;core.Settings.AreDefaultScriptDialogsEnabled=false;core.Settings.IsPasswordAutosaveEnabled=false;core.Settings.IsGeneralAutofillEnabled=false;core.NewWindowRequested+=(s,e)=>e.Handled=true;core.PermissionRequested+=(s,e)=>e.State=CoreWebView2PermissionState.Deny;core.DownloadStarting+=(s,e)=>e.Cancel=true;bool firstNavigation=true;core.NavigationStarting+=(s,e)=>{if(firstNavigation){firstNavigation=false;return;}e.Cancel=true;};core.FrameNavigationStarting+=(s,e)=>e.Cancel=true;core.NavigationCompleted+=async(s,e)=>{if(QaPath!=null)File.AppendAllText(QaPath+".log","navigation "+e.IsSuccess+" "+core.Source+"\n"+await core.ExecuteScriptAsync("JSON.stringify({state:document.readyState,html:document.documentElement.outerHTML.length,uuid:typeof crypto.randomUUID})")+"\n");};core.WebMessageReceived+=async(s,e)=>{if(QaPath!=null)File.AppendAllText(QaPath+".log","message "+e.Source+"\n");if(!e.Source.StartsWith("about:blank",StringComparison.Ordinal))return;try{var data=Api.Json.Deserialize<Dictionary<string,object>>(e.WebMessageAsJson);string op=Api.String(data,"op");if(op=="ready"){ready=true;await Poll();return;}if(op=="announcement"){if(!teacher)throw new Exception("Acceso denegado.");targets=Enumerable.Range(1,33).Select(n=>"UEPLV-"+n.ToString("00")).ToArray();revision=Guid.NewGuid().ToString();Push();return;}if(op=="configure"){if(!teacher)throw new Exception("Acceso denegado.");data["targets"]=Names(data,"targets");await Call(data);await Poll();return;}if(op=="send"){var names=Names(data,"recipients");if(!teacher&&names.Length!=1)throw new Exception("Acceso denegado.");var body=new Dictionary<string,object>{{"op","send"},{"recipients",names},{"text",Api.String(data,"text")},{"requestId",Api.String(data,"requestId")}};await Call(body);core.PostWebMessageAsJson("{\"type\":\"sent\"}");await Poll();}}catch(Exception error){core.PostWebMessageAsJson(Api.Json.Serialize(new{type="error",message=error.Message}));}};using(var stream=typeof(ChatWindow).Assembly.GetManifestResourceStream("chat.html"))using(var reader=new StreamReader(stream))core.NavigateToString(reader.ReadToEnd());}
 string[] Names(Dictionary<string,object> body,string key){object value;if(!body.TryGetValue(key,out value)||!(value is IEnumerable)||value is string)throw new Exception("Destinatarios no válidos.");var names=((IEnumerable)value).Cast<object>().Select(Convert.ToString).ToArray();if(names.Length<1||names.Length>34||names.Any(n=>n!="teacher"&&!System.Text.RegularExpressions.Regex.IsMatch(n,@"^UEPLV-(0[1-9]|[12][0-9]|3[0-4])$")))throw new Exception("Destinatarios no válidos.");return names.Distinct().ToArray();}
    async Task<Dictionary<string,object>> Call(Dictionary<string,object> body){
      if(teacher){if(session==null)session=SessionStore.Load();try{return await Api.Call(session,"chat",body);}catch(LoginRequired){}if(!Visible)throw new Exception("Sin sesión.");using(var login=new LoginForm()){if(login.ShowDialog(this)!=DialogResult.OK)throw new Exception("Sin sesión.");}session=SessionStore.Load();return await Api.Call(session,"chat",body);}
      string path=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.CommonApplicationData),"UEPLV","Chat","student-session.json");
      var config=Api.Json.Deserialize<Dictionary<string,object>>(File.ReadAllText(path));body["token"]=Api.String(config,"token");
      var request=(HttpWebRequest)WebRequest.Create(SessionStore.BaseUrl+"/api/chat/student");request.Method="POST";request.ContentType="application/json";request.AllowAutoRedirect=false;request.Timeout=15000;request.ReadWriteTimeout=15000;
      var bytes=Encoding.UTF8.GetBytes(Api.Json.Serialize(body));request.ContentLength=bytes.Length;
      using(var cancel=new System.Threading.CancellationTokenSource(18000))using(cancel.Token.Register(request.Abort)){
        try{using(var stream=await request.GetRequestStreamAsync())await stream.WriteAsync(bytes,0,bytes.Length);
          using(var response=(HttpWebResponse)await request.GetResponseAsync())using(var stream=response.GetResponseStream())using(var output=new MemoryStream()){
            byte[] buffer=new byte[8192];int n;while((n=await stream.ReadAsync(buffer,0,buffer.Length))>0){if(output.Length+n>524288)throw new Exception("Respuesta no válida.");output.Write(buffer,0,n);}return Api.Json.Deserialize<Dictionary<string,object>>(Encoding.UTF8.GetString(output.ToArray()));}}
        catch(WebException ex){var response=ex.Response as HttpWebResponse;if(response!=null){int code=(int)response.StatusCode;response.Dispose();if(code==403)throw new Exception("Este chat no está permitido.");if(code==429)throw new Exception("Espera unos segundos.");}throw new Exception("Chat sin conexión.");}
      }
    }

 async Task Poll(){if(!ready||busy||exiting)return;busy=true;try{snapshot=await Call(new Dictionary<string,object>{{"op","poll"}});foreach(var message in Api.Objects(snapshot,"messages")){if(seen.Add(Api.String(message,"id"))&&!first&&Api.String(message,"to")==Api.String(snapshot,"name")){tray.BalloonTipTitle="Chat del laboratorio";tray.BalloonTipText=Api.String(message,"text").Substring(0,Math.Min(180,Api.String(message,"text").Length));tray.ShowBalloonTip(5000);}}first=false;Push();string root=teacher?SessionStore.DirectoryPath:Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"UEPLV","Chat");Directory.CreateDirectory(root);File.WriteAllText(Path.Combine(root,teacher?"teacher-chat-state.json":"client-status.json"),Api.Json.Serialize(new{connected=true,webview=true,visible=Visible,mode=Api.String(snapshot,"mode"),contacts=Api.Objects(snapshot,"contacts").Count(),targets}));if(QaPath!=null){string path=QaPath;QaPath=null;await Task.Delay(600);using(var file=File.Create(path+".png"))await view.CoreWebView2.CapturePreviewAsync(CoreWebView2CapturePreviewImageFormat.Png,file);File.WriteAllText(path,Api.Json.Serialize(new{connected=true,webview=true,contacts=Api.Objects(snapshot,"contacts").Count(),mode=Api.String(snapshot,"mode")}));exiting=true;Close();}}catch(Exception error){if(ready)view.CoreWebView2.PostWebMessageAsJson(Api.Json.Serialize(new{type="error",message=error.Message}));}finally{busy=false;}}
 void Push(){if(!ready||snapshot==null)return;var modes=Api.Object(snapshot,"deviceModes");string mode=teacher?(targets.Length>0?Api.String(modes,targets[0]):"teacher-only"):Api.String(snapshot,"mode");view.CoreWebView2.PostWebMessageAsJson(Api.Json.Serialize(new{type="state",teacher,name=Api.String(snapshot,"name"),contacts=Api.Objects(snapshot,"contacts").ToArray(),messages=Api.Objects(snapshot,"messages").ToArray(),targets,selectionRevision=revision,currentMode=mode,connected=true}));}
}}
